import Root from "./audio-provider.svelte";

export {
	Root,
	//
	Root as AudioProvider,
};

import { htmlAudio, type Track } from "$lib/html-audio.js";

export type RepeatMode = "none" | "one" | "all";
export type InsertMode = "first" | "last" | "after";

// ─── Helper functions ────────────────────────────────────────────────────────

export function canUseDOM(): boolean {
	return typeof window !== "undefined" && !!window.document?.createElement;
}

type QueueNavigationParams = {
	queue: Track[];
	currentQueueIndex: number;
	shuffleEnabled: boolean;
	repeatMode: RepeatMode;
};

function getRandomShuffleIndex(queueLength: number, currentIndex: number): number {
	if (queueLength === 1) return 0;
	let idx: number;
	do {
		idx = Math.floor(Math.random() * queueLength);
	} while (idx === currentIndex);
	return idx;
}

function calculateQueueIndex(params: QueueNavigationParams & { direction: 1 | -1 }): number {
	const { queue, currentQueueIndex, shuffleEnabled, repeatMode, direction } = params;
	if (queue.length === 0) return -1;
	if (shuffleEnabled) {
		if (queue.length === 1) return repeatMode === "none" ? -1 : 0;
		return getRandomShuffleIndex(queue.length, currentQueueIndex);
	}
	const next = currentQueueIndex + direction;
	if (next >= queue.length) return repeatMode === "all" ? 0 : -1;
	if (next < 0) return repeatMode === "all" ? queue.length - 1 : -1;
	return next;
}

export function calculateNextIndex(params: QueueNavigationParams): number {
	return calculateQueueIndex({ ...params, direction: 1 });
}

export function calculatePreviousIndex(params: QueueNavigationParams): number {
	return calculateQueueIndex({ ...params, direction: -1 });
}

// ─── Store ───────────────────────────────────────────────────────────────────

const STORAGE_KEY = "audio:ui:store";

class AudioStore {
	// ── Reactive state ──────────────────────────────────────────────────────
	currentTrack: Track | null = $state(null);
	queue: Track[] = $state([]);
	isPlaying = $state(false);
	isLoading = $state(false);
	isBuffering = $state(false);
	volume = $state(1);
	isMuted = $state(false);
	playbackRate = $state(1);
	repeatMode: RepeatMode = $state("none");
	shuffleEnabled = $state(false);
	currentTime = $state(0);
	duration = $state(0);
	progress = $state(0);
	bufferedTime = $state(0);
	insertMode: InsertMode = $state("last");
	isError = $state(false);
	errorMessage: string | null = $state(null);
	currentQueueIndex = $state(-1);

	constructor() {
		if (canUseDOM()) this.loadFromStorage();
	}

	// ── Persistence ─────────────────────────────────────────────────────────

	loadFromStorage(): void {
		try {
			const raw = localStorage.getItem(STORAGE_KEY);
			if (!raw) return;
			const d = JSON.parse(raw);
			if (d.currentTrack !== undefined) this.currentTrack = d.currentTrack;
			if (d.queue !== undefined) this.queue = d.queue;
			if (d.volume !== undefined) this.volume = d.volume;
			if (d.isMuted !== undefined) this.isMuted = d.isMuted;
			if (d.playbackRate !== undefined) this.playbackRate = d.playbackRate;
			if (d.repeatMode !== undefined) this.repeatMode = d.repeatMode;
			if (d.shuffleEnabled !== undefined) this.shuffleEnabled = d.shuffleEnabled;
			if (d.currentTime !== undefined) this.currentTime = d.currentTime;
			if (d.insertMode !== undefined) this.insertMode = d.insertMode;
			if (d.currentQueueIndex !== undefined) this.currentQueueIndex = d.currentQueueIndex;
		} catch {
			/* ignore */
		}
	}

	saveToStorage(): void {
		if (!canUseDOM()) return;
		try {
			localStorage.setItem(
				STORAGE_KEY,
				JSON.stringify({
					currentTrack: this.currentTrack,
					queue: this.queue,
					volume: this.volume,
					isMuted: this.isMuted,
					playbackRate: this.playbackRate,
					repeatMode: this.repeatMode,
					shuffleEnabled: this.shuffleEnabled,
					currentTime: this.currentTime,
					insertMode: this.insertMode,
					currentQueueIndex: this.currentQueueIndex,
				})
			);
		} catch {
			/* ignore */
		}
	}

	// ── Playback actions ────────────────────────────────────────────────────

	play(): void {
		if (this.isLoading) return;
		this.isPlaying = true;
		htmlAudio.play().catch(() => {});
	}

	pause(): void {
		this.isPlaying = false;
		htmlAudio.pause();
	}

	togglePlay(): void {
		if (this.isLoading) return;
		if (this.isPlaying) {
			this.pause();
		} else {
			this.play();
		}
	}

	seek(time: number): void {
		const valid = this.duration > 0 ? Math.max(0, Math.min(time, this.duration)) : time;
		this.currentTime = valid;
		this.progress = this.duration > 0 ? (valid / this.duration) * 100 : 0;
	}

	next(): void {
		const idx = calculateNextIndex({
			queue: this.queue,
			currentQueueIndex: this.currentQueueIndex,
			shuffleEnabled: this.shuffleEnabled,
			repeatMode: this.repeatMode,
		});
		const track = this.queue[idx];
		if (idx === -1 || !track) {
			this.isLoading = false;
			this.isPlaying = false;
			this.isBuffering = false;
			return;
		}
		this.loadAndPlayTrack(track, idx);
	}

	previous(): void {
		if (this.currentTime > 3 && !this.shuffleEnabled) {
			this.currentTime = 0;
			this.progress = 0;
			return;
		}
		const idx = calculatePreviousIndex({
			queue: this.queue,
			currentQueueIndex: this.currentQueueIndex,
			shuffleEnabled: this.shuffleEnabled,
			repeatMode: this.repeatMode,
		});
		const track = this.queue[idx];
		if (idx === -1 || !track) {
			this.isLoading = false;
			this.isPlaying = false;
			this.isBuffering = false;
			return;
		}
		this.loadAndPlayTrack(track, idx);
	}

	setQueueAndPlay(songs: Track[], startIndex: number): void {
		const target = songs[startIndex];
		if (!target) {
			this.clearQueue();
			this.isPlaying = false;
			this.isLoading = false;
			this.currentTrack = null;
			this.currentQueueIndex = -1;
			return;
		}
		this.setQueue(songs, startIndex);
		this.loadAndPlayTrack(target, startIndex);
	}

	handleTrackEnd(): void {
		this.next();
	}

	// ── Queue actions ───────────────────────────────────────────────────────

	setQueue(tracks: Track[], startIndex = 0): void {
		const current = tracks[startIndex] ?? null;
		this.queue = tracks;
		this.currentQueueIndex = current ? startIndex : -1;
		this.currentTrack = current;
	}

	getCurrentQueueIndex(): number {
		return this.currentQueueIndex;
	}

	addToQueue(track: Track, mode: InsertMode = "last"): void {
		if (!this.currentTrack) {
			this.currentTrack = track;
			this.currentQueueIndex = 0;
			this.queue = [track];
			return;
		}
		switch (mode) {
			case "first":
				this.queue = [track, ...this.queue];
				this.currentQueueIndex++;
				break;
			case "after":
				this.queue = [
					...this.queue.slice(0, this.currentQueueIndex + 1),
					track,
					...this.queue.slice(this.currentQueueIndex + 1),
				];
				break;
			default:
				this.queue = [...this.queue, track];
		}
	}

	removeFromQueue(trackId: string): void {
		const idx = this.queue.findIndex((s) => s.id === trackId);
		if (idx === -1) return;
		this.queue = this.queue.filter((s) => s.id !== trackId);
		if (idx < this.currentQueueIndex) this.currentQueueIndex--;
	}

	clearQueue(): void {
		this.queue = [];
	}

	moveInQueue(fromIndex: number, toIndex: number): void {
		const q = [...this.queue];
		const [item] = q.splice(fromIndex, 1);
		if (!item) return;
		q.splice(toIndex, 0, item);
		this.queue = q;
	}

	addTracksToEndOfQueue(tracks: Track[]): void {
		if (!tracks?.length) return;
		const ids = new Set(this.queue.map((s) => s.id));
		const newTracks = tracks.filter((t) => !ids.has(t.id));
		if (newTracks.length) this.queue = [...this.queue, ...newTracks];
	}

	// ── Control actions ─────────────────────────────────────────────────────

	setVolume(params: { volume: number }): void {
		this.volume = params.volume;
		this.isMuted = params.volume === 0;
	}

	toggleMute(): void {
		this.isMuted = !this.isMuted;
	}

	setPlaybackRate(rate: number): void {
		if (this.duration && htmlAudio.isLive(this.duration)) return;
		this.playbackRate = Math.max(0.25, Math.min(2, rate));
	}

	changeRepeatMode(): void {
		const modes: RepeatMode[] = ["none", "one", "all"];
		const i = modes.indexOf(this.repeatMode);
		this.repeatMode = modes[(i + 1) % modes.length] as RepeatMode;
	}

	setRepeatMode(mode: RepeatMode): void {
		this.repeatMode = mode;
	}
	setInsertMode(mode: InsertMode): void {
		this.insertMode = mode;
	}

	shuffle(): void {
		if (!this.queue.length || this.queue.length < 2 || !this.currentTrack) return;
		const rest = this.queue.filter((_, i) => i !== this.currentQueueIndex);
		const shuffled = rest.sort(() => Math.random() - 0.5);
		this.queue = [this.currentTrack, ...shuffled];
		this.currentQueueIndex = 0;
		this.shuffleEnabled = true;
	}

	unshuffle(): void {
		this.shuffleEnabled = false;
	}

	// ── State actions ───────────────────────────────────────────────────────

	setCurrentTrack(track: Track | null): void {
		if (!track) {
			this.currentTrack = null;
			this.currentQueueIndex = -1;
			this.isPlaying = false;
			this.currentTime = 0;
			this.duration = 0;
			this.queue = [];
			this.isLoading = false;
			this.isError = false;
			this.errorMessage = null;
			return;
		}
		if (this.currentTrack?.id === track.id) return;
		this.currentTrack = track;
		this.queue = [track];
		this.currentQueueIndex = 0;
		this.isLoading = true;
		this.isPlaying = false;
		this.currentTime = 0;
		this.duration = 0;
		this.isError = false;
		this.errorMessage = null;
		this.loadAndPlayTrack(track, 0);
	}

	/** Called by AudioProvider to sync audio element time into state. */
	syncTime(currentTime: number, duration: number): void {
		this.currentTime = currentTime;
		this.duration = duration;
		this.progress = duration > 0 ? (currentTime / duration) * 100 : 0;
	}

	setError(message: string | null): void {
		this.isError = !!message;
		this.errorMessage = message;
		this.isLoading = false;
		this.isPlaying = false;
	}

	/**
	 * Sets state to signal the provider to load and play a track.
	 * The actual audio loading is handled by AudioProvider via $effect.
	 */
	loadAndPlayTrack(track: Track, queueIndex: number): void {
		const isLiveStream =
			track.live === true ||
			(track.duration !== undefined && htmlAudio.isLive(track.duration));

		this.currentTrack = track;
		this.currentQueueIndex = queueIndex;
		this.isError = false;
		this.errorMessage = null;

		if (isLiveStream && this.playbackRate !== 1) this.playbackRate = 1;

		// Signal provider: set isPlaying=true to trigger load+play effect
		this.isLoading = false;
		this.isBuffering = false;
		this.isPlaying = true;
	}
}

export const audioStore = new AudioStore();

export type Track = {
	id?: string | number;
	url: string;
	title?: string;
	artist?: string;
	artwork?: string;
	images?: string[];
	duration?: number;
	album?: string;
	genre?: string;
	live?: boolean;
	[key: string]: unknown;
};

type LoadParams = {
	url: string;
	startTime?: number;
	isLiveStream?: boolean;
};

type SetVolumeParams = {
	volume: number;
	fadeTime?: number;
};

type FadeVolumeParams = {
	audio: HTMLAudioElement;
	targetVolume: number;
	duration: number;
};

class HtmlAudio {
	private audio: HTMLAudioElement | null = null;
	private isInitialized = false;
	private playPromise: Promise<void> | null = null;
	private lastVolume = 1;
	private fadeTimeout: ReturnType<typeof setTimeout> | null = null;
	private retryAttempts = 0;
	private readonly maxRetries = 3;
	private readonly eventTarget = new EventTarget();
	private readonly LOAD_TIMEOUT_LIVE = 60_000;
	private readonly LOAD_TIMEOUT_NORMAL = 30_000;
	private readonly FADE_UPDATE_INTERVAL = 16;

	init(): void {
		if (this.isInitialized || !this.isClient()) return;
		this.isInitialized = true;
		if (this.isClient()) {
			this.audio = new Audio();
			this.setupEventListeners();
		}
	}

	private setupEventListeners(): void {
		if (!this.isClient()) return;
		const audio = this.ensureAudio();
		if (!audio) return;

		audio.addEventListener("error", () => {
			if (this.retryAttempts < this.maxRetries) {
				this.retryAttempts++;
				setTimeout(() => this.reloadAudio(), 1000);
			}
			this.eventTarget.dispatchEvent(new CustomEvent("audioError"));
		});

		audio.addEventListener("playing", () => {
			this.retryAttempts = 0;
			this.eventTarget.dispatchEvent(new CustomEvent("bufferingEnd"));
			this.eventTarget.dispatchEvent(new CustomEvent("playbackStarted"));
		});

		audio.addEventListener("canplaythrough", () => {
			this.retryAttempts = 0;
			this.eventTarget.dispatchEvent(new CustomEvent("bufferingEnd"));
		});

		audio.addEventListener("waiting", () => {
			this.eventTarget.dispatchEvent(new CustomEvent("bufferingStart"));
		});

		audio.addEventListener("progress", () => {
			const buffered = audio.buffered;
			const currentTime = audio.currentTime;
			let bufferedEnd = 0;
			if (buffered.length === 0) return;

			for (let i = buffered.length - 1; i >= 0; i--) {
				if (buffered.start(i) <= currentTime) {
					bufferedEnd = buffered.end(i);
					break;
				}
			}
			if (bufferedEnd === 0) bufferedEnd = buffered.end(0);
			if (bufferedEnd > 0) {
				this.eventTarget.dispatchEvent(
					new CustomEvent("bufferUpdate", { detail: { bufferedTime: bufferedEnd } })
				);
			}
		});
	}

	cleanup(): void {
		if (this.audio) {
			this.audio.pause();
			this.audio.src = "";
			this.audio.load();
		}
		if (this.fadeTimeout) {
			clearTimeout(this.fadeTimeout);
			this.fadeTimeout = null;
		}
		this.playPromise = null;
	}

	getAudioElement(): HTMLAudioElement | null {
		if (!this.isClient()) return null;
		return this.audio;
	}

	private isClient(): boolean {
		return typeof window !== "undefined" && !!window.document;
	}

	private ensureAudio(): HTMLAudioElement {
		if (!this.isClient()) throw new Error("Audio module not available on server side");
		if (!this.audio) throw new Error("Audio module not initialized");
		return this.audio;
	}

	private ifClient<T>(fn: () => T): T | undefined {
		if (!this.isClient()) return;
		return fn();
	}

	async load(params: LoadParams): Promise<void> {
		const { url, startTime = 0, isLiveStream = false } = params;
		const result = this.ifClient(() => this._load({ url, startTime, isLiveStream }));
		if (result) await result;
	}

	private async _load(params: {
		url: string;
		startTime: number;
		isLiveStream: boolean;
	}): Promise<void> {
		const { url, startTime, isLiveStream } = params;
		const audio = this.ensureAudio();
		if (!audio) return;

		try {
			this.retryAttempts = 0;
			if (audio.src === url) {
				if (audio.currentTime !== startTime && !isLiveStream) audio.currentTime = startTime;
				return;
			}

			audio.pause();
			audio.src = "";
			audio.src = url;
			audio.preload = "auto";

			const loadTimeout = isLiveStream ? this.LOAD_TIMEOUT_LIVE : this.LOAD_TIMEOUT_NORMAL;

			await new Promise<void>((resolve, reject) => {
				let timeoutId: ReturnType<typeof setTimeout> | null = null;
				let isResolved = false;

				const cleanup = () => {
					if (timeoutId) {
						clearTimeout(timeoutId);
						timeoutId = null;
					}
					audio.removeEventListener("loadedmetadata", handleLoadSuccess);
					audio.removeEventListener("canplay", handleLoadSuccess);
					audio.removeEventListener("canplaythrough", handleLoadSuccess);
					audio.removeEventListener("error", handleErrorLoading);
				};

				const handleTimeout = () => {
					if (isResolved) return;
					isResolved = true;
					cleanup();
					reject(new Error(`Audio load timeout (${loadTimeout / 1000}s)`));
				};

				const handleLoadSuccess = () => {
					if (isResolved) return;
					isResolved = true;
					cleanup();
					if (startTime > 0 && !isLiveStream) audio.currentTime = startTime;
					resolve();
				};

				const handleErrorLoading = () => {
					if (isResolved) return;
					isResolved = true;
					cleanup();
					const error = audio.error;
					reject(
						new Error(
							`Audio load failed: ${error?.message || `code ${error?.code ?? "unknown"}`}`
						)
					);
				};

				timeoutId = setTimeout(handleTimeout, loadTimeout);
				audio.addEventListener("loadedmetadata", handleLoadSuccess);
				audio.addEventListener("canplay", handleLoadSuccess);
				audio.addEventListener("canplaythrough", handleLoadSuccess);
				audio.addEventListener("error", handleErrorLoading);
				audio.load();
			});
		} catch (error) {
			console.error("Audio load process error:", error);
			throw error;
		}
	}

	async play(): Promise<void> {
		const result = this.ifClient(() => this._play());
		if (result) await result;
	}

	private async _play(): Promise<void> {
		if (!this.audio) throw new Error("Audio module not initialized");
		try {
			if (!this.audio.paused) return;
			this.playPromise = this.audio.play();
			await this.playPromise;
			this.playPromise = null;
		} catch (error) {
			this.playPromise = null;
			throw error;
		}
	}

	private reloadAudio(): void {
		if (!this.isClient()) return;
		const audio = this.ensureAudio();
		const currentTime = audio.currentTime;
		const wasPlaying = !audio.paused;
		const currentSrc = audio.src;

		audio.pause();
		audio.src = "";
		audio.load();
		audio.src = currentSrc;
		audio.preload = "auto";
		audio.load();

		const setTimeAndPlay = () => {
			if (audio.readyState >= audio.HAVE_METADATA) {
				audio.currentTime = currentTime;
				if (wasPlaying) this.play().catch(() => {});
				audio.removeEventListener("loadedmetadata", setTimeAndPlay);
			}
		};
		audio.addEventListener("loadedmetadata", setTimeAndPlay);
	}

	pause(): void {
		this.ifClient(() => {
			const audio = this.ensureAudio();
			audio.pause();
		});
	}

	setVolume(params: SetVolumeParams): void {
		const { volume, fadeTime = 0 } = params;
		this.ifClient(() => {
			const audio = this.ensureAudio();
			if (this.fadeTimeout) {
				clearTimeout(this.fadeTimeout);
				this.fadeTimeout = null;
			}
			if (fadeTime <= 0) {
				audio.volume = Math.max(0, Math.min(1, volume));
				if (volume > 0) this.lastVolume = volume;
				return;
			}
			this.fadeVolume({ audio, targetVolume: volume, duration: fadeTime });
		});
	}

	private fadeVolume(params: FadeVolumeParams): void {
		const { audio, targetVolume, duration } = params;
		if (!this.isClient()) return;
		const startVolume = audio.volume;
		const endVolume = Math.max(0, Math.min(1, targetVolume));
		const startTime = performance.now();

		const updateVolume = () => {
			const elapsed = performance.now() - startTime;
			const progress = Math.min(1, elapsed / duration);
			audio.volume = startVolume + (endVolume - startVolume) * progress;
			if (progress < 1) {
				this.fadeTimeout = setTimeout(updateVolume, this.FADE_UPDATE_INTERVAL);
			} else {
				if (endVolume > 0) this.lastVolume = endVolume;
				this.fadeTimeout = null;
			}
		};
		updateVolume();
	}

	getVolume(): number {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.volume;
			}) ?? 0
		);
	}

	setMuted(muted: boolean): void {
		this.ifClient(() => {
			const audio = this.ensureAudio();
			if (audio.muted === muted) return;
			if (muted) {
				if (audio.volume > 0) this.lastVolume = audio.volume;
				this.fadeVolume({ audio, targetVolume: 0, duration: 200 });
				audio.muted = true;
			} else {
				audio.muted = false;
				this.fadeVolume({ audio, targetVolume: this.lastVolume, duration: 200 });
			}
		});
	}

	getDuration(): number {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.duration;
			}) ?? 0
		);
	}
	getCurrentTime(): number {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.currentTime;
			}) ?? 0
		);
	}

	setCurrentTime(time: number): void {
		this.ifClient(() => {
			const audio = this.ensureAudio();
			const duration = audio.duration;
			if (Number.isNaN(duration)) return;
			const validTime =
				time >= 0 && time <= duration ? time : Math.max(0, Math.min(time, duration));
			if (audio.readyState >= audio.HAVE_METADATA) audio.currentTime = validTime;
		});
	}

	addEventListener(
		type: string,
		listener: EventListenerOrEventListenerObject | null,
		options?: boolean | AddEventListenerOptions
	): void {
		this.eventTarget.addEventListener(type, listener, options);
	}

	removeEventListener(
		type: string,
		callback: EventListenerOrEventListenerObject | null,
		options?: EventListenerOptions | boolean
	): void {
		this.eventTarget.removeEventListener(type, callback, options);
	}

	getSource(): string {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.src;
			}) ?? ""
		);
	}
	isPaused(): boolean {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.paused;
			}) ?? true
		);
	}

	getBufferedRanges(): TimeRanges | null {
		if (!this.isClient() || !this.audio) return null;
		return this.audio.buffered;
	}

	setPlaybackRate(rate: number): void {
		this.ifClient(() => {
			const audio = this.ensureAudio();
			if (this.isLive(audio.duration)) return;
			audio.playbackRate = Math.max(0.25, Math.min(2, rate));
		});
	}

	getPlaybackRate(): number {
		return (
			this.ifClient(() => {
				const a = this.ensureAudio();
				return a.playbackRate;
			}) ?? 1
		);
	}

	isLive(duration: number): boolean {
		if (duration === 0) return false;
		return (
			Number.isNaN(duration) ||
			duration === Number.POSITIVE_INFINITY ||
			duration === Number.NEGATIVE_INFINITY
		);
	}
}

export const htmlAudio = new HtmlAudio();

const MINUTE_IN_SECONDS = 60;

export function formatDuration(seconds: number): string {
	if (!Number.isFinite(seconds) || seconds < 0) return "0:00";
	const minutes = Math.floor(seconds / MINUTE_IN_SECONDS);
	const remainingSeconds = Math.floor(seconds % MINUTE_IN_SECONDS);
	return `${minutes}:${remainingSeconds < 10 ? "0" : ""}${remainingSeconds}`;
}
